@@ -0,0 +1,51 @@
+//go:build linux
+
+package engine
+
+import "testing"
+
+func TestPlanningScopeOwnActivationBudgetDiscriminant(t *testing.T) {
+	for _, limit := range []int{1, 2} {
+		t.Run(map[int]string{1: "one", 2: "two"}[limit], func(t *testing.T) {
+			s, w := planningFixture(t)
+			w, r := planningClaim(t, s, w, "root")
+			r.Operations = []PlanningOperation{{Kind: "delegate", ID: "bounded-child", Title: "Bounded scope", Requirements: []string{"req-1"}, MaxActivations: limit}}
+			var err error
+			w, err = s.planningChange(w.ID, "decide", r)
+			if err != nil {
+				t.Fatal(err)
+			}
+			for i := 0; i < limit; i++ {
+				if i > 0 {
+					w = planningDo(t, s, w, "resume", PlanningRequest{Scope: "bounded-child", Reason: "New attributed event after the prior decision"})
+				}
+				w, r = planningClaim(t, s, w, "bounded-child")
+				child, _ := w.Planning.scope("bounded-child")
+				root, _ := w.Planning.scope("root")
+				if child.Activations != i+1 || root.Activations != i+2 || w.Planning.Activations != i+2 {
+					t.Fatal("claim did not charge self and ancestor exactly once", child.Activations, root.Activations, w.Planning.Activations)
+				}
+				w, err = s.planningChange(w.ID, "decide", r)
+				if err != nil {
+					t.Fatal(err)
+				}
+			}
+			w = planningDo(t, s, w, "resume", PlanningRequest{Scope: "bounded-child", Reason: "A fresh event cannot bypass the exhausted local budget"})
+			before := w
+			child, _ := w.Planning.scope("bounded-child")
+			req := PlanningRequest{Schema: 1, EventID: newID("refused-claim-"), Revision: w.Revision, Scope: child.ID, ScopeRevision: child.Revision, Holder: "test-owner", LeaseSeconds: 60}
+			if _, err = s.planningChange(w.ID, "claim", req); err == nil || commandFailure(err).Code != "budget_exhausted" {
+				t.Fatal("own activation limit did not refuse a successive claim", err)
+			}
+			got, err := s.get(w.ID)
+			if err != nil {
+				t.Fatal(err)
+			}
+			child, _ = got.Planning.scope("bounded-child")
+			if got.Revision != before.Revision || child.Activations != limit || got.Planning.Activations != before.Planning.Activations || child.Holder != "" {
+				t.Fatal("refusal changed counters, revision or reservation")
+			}
+			t.Logf("self=%d ancestor/global=%d; next claim refused budget_exhausted with state unchanged; no model called", child.Activations, got.Planning.Activations)
+		})
+	}
+}

