	Paused                bool                           `json:"paused"`
	MaxTasks              int                            `json:"max_tasks"`
	MaxDecisions          int                            `json:"max_decisions"`
	Decisions             int                            `json:"decisions"`
	Scopes                []PlanningScope                `json:"scopes"`
	Inbox                 []PlanningEvent                `json:"inbox"`
